function auditHash(e, previousHash) {
  return sha256(`${e.id}:${e.timestamp}:${e.actorId}:${e.actorRole}:${e.entityType}:${e.entityId}:${e.action}:${e.details}:${previousHash}`);
}
var GENESIS_HASH = "0".repeat(64);
function verifyChain(events) {
  let prev = GENESIS_HASH;
  for (let i = 0; i < events.length; i++) {
    const ev2 = events[i];
    if (ev2.previousHash !== prev || ev2.hash !== auditHash(ev2, prev)) {
      return { isValid: false, checkedCount: i, brokenEventId: ev2.id };
    }
    prev = ev2.hash;
  }
  return { isValid: true, checkedCount: events.length };
}
